    private static Function<Item.Settings, Item> createBlockItemWithUniqueName(Block block) {
        return settings -> new ModFoodItem(block, settings.useItemPrefixedTranslationKey());
    }

    private static Item createFoodItem(String id, Item.Settings settings) {
        return ItemsCover.register(ItemsCover.keyOf(id), ModFoodItem::new, settings);
    }

    private static RegistryKey<Item> keyOf(String id) {
        return RegistryKey.of(RegistryKeys.ITEM, Identifier.ofVanilla(id));
    }

    private static RegistryKey<Item> keyOf(RegistryKey<Block> blockKey) {
        return RegistryKey.of(RegistryKeys.ITEM, blockKey.getValue());
    }
    private static Item register(Block block , int maxCount) {
        return ItemsCover.register(block, BlockItem::new , new Item.Settings().maxCount(maxCount));
    }
    public static Item register(Block block) {
        return ItemsCover.register(block, BlockItem::new);
    }

    public static Item register(Block block, Item.Settings settings) {
        return ItemsCover.register(block, BlockItem::new, settings);
    }

    public static Item register(Block block, UnaryOperator<Item.Settings> settingsOperator) {
        return ItemsCover.register(block, (Block blockx, Item.Settings settings) -> new BlockItem(blockx, settingsOperator.apply(settings)));
    }

    public static Item register(Block block, Block ... blocks) {
        Item item = ItemsCover.register(block);
        for (Block block2 : blocks) {
            Item.BLOCK_ITEMS.put(block2, item);
        }
        return item;
    }

    public static Item register(Block block, BiFunction<Block, Item.Settings, Item> factory) {
        return ItemsCover.register(block, factory, new Item.Settings().maxCount(8));
    }

    public static Item register(Block block, BiFunction<Block, Item.Settings, Item> factory, Item.Settings settings) {
        return ItemsCover.register(ItemsCover.keyOf(Registries.BLOCK.getId(block).getPath()), (Item.Settings itemSettings) -> factory.apply(block, itemSettings), settings.useBlockPrefixedTranslationKey());
    }

    public static Item register(String id, Function<Item.Settings, Item> factory) {
        return ItemsCover.register(ItemsCover.keyOf(id), factory, new Item.Settings());
    }

    public static Item register(String id, Function<Item.Settings, Item> factory, Item.Settings settings) {
        return ItemsCover.register(ItemsCover.keyOf(id), factory, settings);
    }

    public static Item register(String id, Item.Settings settings) {
        return ItemsCover.register(ItemsCover.keyOf(id), Item::new, settings);
    }

    public static Item register(String id) {
        return ItemsCover.register(ItemsCover.keyOf(id), Item::new, new Item.Settings());
    }

    public static Item register(RegistryKey<Item> key, Function<Item.Settings, Item> factory) {
        return ItemsCover.register(key, factory, new Item.Settings());
    }

    public static Item register(RegistryKey<Item> key, Function<Item.Settings, Item> factory, Item.Settings settings) {
        Item item = factory.apply(settings.registryKey(key));
        if (item instanceof BlockItem blockItem) {
            blockItem.appendBlocks(Item.BLOCK_ITEMS, item);
        }
        Item RegisteredItem = Registry.register(Registries.ITEM , key ,item);
        ItemCoverMap.put(key, RegisteredItem);
        return RegisteredItem;
    }
    public static void registeritemsCover() {
        MITENewWorld.LOGGER.info("Registering ItemsCover");
    }
